// TLM access helpers for the hybrid shared-memory doctests, over SimpleMemory.
// Lightweight temp-file helpers live in test_tmpfile.hpp (no SystemC dep).
// Include AFTER `#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN` + <doctest.h>.

#include "platform/simple_memory.hpp"
#include "test_tmpfile.hpp"

#include <doctest.h>
#include <systemc>
#include <tlm>

#include <cstdint>
#include <span>

namespace hybrid::test {

// One blocking TLM access against `mem`, asserting an OK response. `data` is
// the write source for TLM_WRITE / the read destination for TLM_READ.
template<typename Mem>
inline void tlm_access(Mem& mem, tlm::tlm_command cmd, uint64_t addr,
                       std::span<uint8_t> data)
{
  tlm::tlm_generic_payload gp;
  gp.set_command(cmd);
  gp.set_address(addr);
  gp.set_data_ptr(data.data());
  gp.set_data_length(data.size());
  gp.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
  sc_core::sc_time delay = sc_core::SC_ZERO_TIME;
  mem.b_transport(gp, delay);
  REQUIRE(gp.get_response_status() == tlm::TLM_OK_RESPONSE);
}

template<typename Mem>
inline void tlm_write(Mem& mem, uint64_t addr, std::span<uint8_t> data)
{
  tlm_access(mem, tlm::TLM_WRITE_COMMAND, addr, data);
}

template<typename Mem>
inline void tlm_read(Mem& mem, uint64_t addr, std::span<uint8_t> out)
{
  tlm_access(mem, tlm::TLM_READ_COMMAND, addr, out);
}

}  // namespace hybrid::test
#pragma once

// Lightweight, SystemC-free scaffolding shared by the hybrid file-IO doctests:
// a per-process unique temp path and a raw binary-file writer.

#include <unistd.h>

#include <cstddef>
#include <filesystem>
#include <fstream>
#include <string>

namespace hybrid::test {

// Collision-free temp path: prefix + caller tag + pid. Any stale file is
// removed up front so the caller starts clean.
inline auto unique_tmp_path(const char* tag) -> std::string
{
  auto p = std::filesystem::temp_directory_path()
           / (std::string{"vsim_test_"} + tag + "_" + std::to_string(::getpid()));
  std::filesystem::remove(p);
  return p.string();
}

// Write n raw bytes from `data` to `path`, truncating any existing file.
inline void write_binary_file(const std::string& path, const void* data,
                              std::size_t n)
{
  std::ofstream f(path, std::ios::binary | std::ios::trunc);
  f.write(static_cast<const char*>(data), static_cast<std::streamsize>(n));
}

}  // namespace hybrid::test

// vsim's main RAM must cover QEMU's `virt`-machine RAM base (0x80000000) so
// the same ELF can be loaded at the same physical address in both halves of
// the hybrid handoff. The cap stays below NDS_HVM_BASE (0x90000000), which
// is the CPU's slave-port HVM region; further peripherals (ILM, ACM, AIA,
// SMU, UART) start at 0xA0000000+.

#include "platform/memory_map.h"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include <cstdint>

constexpr uint64_t kNdsHvmBase = 0x90000000ULL;

TEST_CASE("RAM region covers QEMU virt RAM base 0x80000000")
{
  CHECK(static_cast<uint64_t>(RAM_END) >= 0x80000000ULL);
}

TEST_CASE("RAM region does not collide with NDS_HVM_BASE")
{
  CHECK(static_cast<uint64_t>(RAM_END) < kNdsHvmBase);
}

TEST_CASE("RAM region does not collide with HART0 ILM peripheral")
{
  CHECK(static_cast<uint64_t>(RAM_END) < static_cast<uint64_t>(HART0_ILM_BASE));
}

// Pin the GPA-to-file-offset contract for hybrid shared mode: a narrow RAM
// region [base, base+size) over an mmap span translates GPA `base + N` to
// file offset `N`, so QEMU and vsim see identical bytes through the same
// backing file. Also guards against SimpleMemory's size-check rejecting an
// external buffer sized to match a sub-2.25 GB region.

#include "platform/mmap_backing.hpp"
#include "platform/simple_memory.hpp"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include "test_helpers.hpp"

#include <fcntl.h>
#include <sys/mman.h>
#include <unistd.h>

#include <array>
#include <filesystem>

using namespace hybrid::test;

TEST_CASE("narrow QEMU-virt region maps GPA 0x80010000 to file offset 0x10000")
{
  const auto path = unique_tmp_path("offset_write");
  constexpr std::size_t kSize = 8 * 1024 * 1024;
  constexpr uint64_t kBaseGpa = 0x80000000;

  MmapBacking backing(path, kSize);

  SimpleMemory<32> mem{
    "mem", MemoryRegion{kBaseGpa, kBaseGpa + kSize - 1},
    MemoryRegion{SimpleMemory<32>::INVALID_ADDRESS,
                 SimpleMemory<32>::INVALID_ADDRESS},
    backing.span()};

  std::array<uint8_t, 8> pattern{0xde, 0xad, 0xbe, 0xef,
                                  0xca, 0xfe, 0xba, 0xbe};
  tlm_write(mem, kBaseGpa + 0x10000, pattern);

  const int fd = ::open(path.c_str(), O_RDONLY);
  REQUIRE(fd >= 0);
  void* p = ::mmap(nullptr, kSize, PROT_READ, MAP_SHARED, fd, 0);
  REQUIRE(p != MAP_FAILED);
  auto* file_bytes = static_cast<const uint8_t*>(p);
  for (std::size_t i = 0; i < pattern.size(); ++i)
    CHECK(file_bytes[0x10000 + i] == pattern[i]);
  ::munmap(p, kSize);
  ::close(fd);
  std::filesystem::remove(path);
}

TEST_CASE("bytes pre-placed at file offset 0x10000 read back as GPA 0x80010000")
{
  const auto path = unique_tmp_path("offset_read");
  constexpr std::size_t kSize = 8 * 1024 * 1024;
  constexpr uint64_t kBaseGpa = 0x80000000;

  MmapBacking backing(path, kSize);
  backing.span()[0x10000 + 0] = 0xa5;
  backing.span()[0x10000 + 1] = 0x5a;

  SimpleMemory<32> mem{
